import * as THREE from 'three/webgpu';
import { sampler2D, uv, positionLocal, normalLocal, mul, add, float } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const basePosition = config.position;

  // Create tessellated plane (64x64 segments for detailed displacement)
  // Aspect ratio: 512/320 = 1.6
  const geometry = new THREE.PlaneGeometry(1.6, 1, 64, 64);

  // Load color and depth textures
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Create material with machined-metal aesthetic
  const material = new THREE.MeshStandardMaterial({
    map: colorTexture,
    metalness: 0.35,      // Machined metal (≤0.55)
    roughness: 0.55,      // Slightly worn surface (≥0.5)
    clearcoat: 0.2        // Subtle clearcoat (≤0.25)
  });

  // Add displacement mapping via TSL nodes
  const depthSampler = sampler2D(depthTexture);
  const displacementScale = float(0.02);

  // Displace vertices along normals based on depth texture
  material.positionNode = add(
    positionLocal,
    mul(normalLocal, mul(depthSampler.sample(uv()).r, displacementScale))
  );

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(basePosition[0], basePosition[1], basePosition[2]);
  mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);
  mesh.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);

  // State for GSAP animations
  const animState = { y: basePosition[1] };
  let activeTimeline = null;

  // Event handlers
  mesh.userData.handlers = {
    pointerenter: () => {
      if (activeTimeline) activeTimeline.kill();
      activeTimeline = gsap.to(animState, {
        y: basePosition[1] + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        onUpdate: () => {
          mesh.position.y = animState.y;
        }
      });
    },
    pointerleave: () => {
      if (activeTimeline) activeTimeline.kill();
      activeTimeline = gsap.to(animState, {
        y: basePosition[1],
        duration: 0.7,
        ease: 'power3.out',
        onUpdate: () => {
          mesh.position.y = animState.y;
        }
      });
    },
    click: () => {
      if (config.emit) {
        config.emit('hub-features.select', {});
      }
    }
  };

  // Cleanup function
  mesh.userData.cleanup = () => {
    if (activeTimeline) activeTimeline.kill();
    gsap.killTweensOf(animState);
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return mesh;
}
